// 16 x 16 JPEG tiles of one colour, RGB (230, 150, 190), written by Pillow.

// A JFIF file with YCbCr 4:2:0 components (Leica GT450 tiles are like this).
export const JFIF_YCBCR_TILE = base64Bytes(
  '',
)

// An Aperio-style tile: RGB components with IDs 0, 1, 2 and no JFIF or Adobe
// marker, its quantization and Huffman tables split off as JPEGTables.
export const APERIO_RGB_JPEG_TABLES = base64Bytes(
  '',
)
export const APERIO_RGB_JPEG_TILE = base64Bytes(
  '/9j/wAARCAAQABADABEAAREAAhEA/9oADAMAAAEAAgAAPwD9mK9Yr74ooooooooor//Z',
)

export const JPEG_FIXTURE_COLOR = [230, 150, 190] as const

function base64Bytes(base64: string): Uint8Array {
  return Uint8Array.from(atob(base64), (character) => character.charCodeAt(0))
}
